#include <cstdio>
#include "pp/diagnostic_memory.h"
#include "pp/diagnostic_trace.h"
using namespace pp; using namespace pp::diagnostic;
static Message start(uint32_t c){Message m{};m.type=Type::StartRequest;m.correlation=c;return m;}
static Message operation(uint32_t c,SessionOperation op){Message m{};m.type=Type::SessionOperationRequest;m.correlation=c;m.operation=op;return m;}
static Message result(uint32_t c,RequestResult r,RequestRejection reason=RequestRejection::None){Message m{};m.type=Type::RequestResult;m.correlation=c;m.requestResult=r;m.rejection=reason;return m;}
static Message notice(){Message m{};m.type=Type::NoticeboardChanged;m.eventId=77;return m;}
int main(){
 MemoryDiagnosticStorage storage;InMemoryDiagnosticRecorder recorder(storage);SessionStartRequest session{};session.controllerEpoch.value=500;session.client.value=1;SessionStatus status{};if(recorder.start(session,status)!=RecorderResult::Accepted)return 1;ControllerOperationTrace trace(recorder);ClientId browser{};browser.value=42;const uint64_t traceId=0x123456789ULL;
 trace.observeBrowserAction(OperationName::Start,17,browser,traceId,10);trace.observeBrowserAction(OperationName::Start,17,browser,traceId+1,10);trace.observeInterfaceRequest(OperationName::Start,17,101,browser,traceId,11);trace.observe(start(101),1,12);trace.observe(result(101,RequestResult::Accepted),2,13);trace.observe(notice(),2,14);if(recorder.count()!=7)return 2;RecordEnvelope e{};uint8_t payload[4]{};size_t length=0;const EventKind expected[]={EventKind::UserAction,EventKind::UserAction,EventKind::BrowserRequest,EventKind::BusRequest,EventKind::RequestAccepted,EventKind::StateChange,EventKind::NoticeboardChanged};for(size_t i=0;i<7;++i){if(!recorder.read(i,e,payload,sizeof(payload),length)||e.kind!=expected[i]||e.operation!=OperationName::Start||e.client.value!=42)return 3;}if(e.traceId!=traceId||e.correlation.request!=101||e.correlation.parent!=17||e.correlation.event!=77)return 4;
 MemoryDiagnosticStorage secondStorage;InMemoryDiagnosticRecorder secondRecorder(secondStorage);if(secondRecorder.start(session,status)!=RecorderResult::Accepted)return 5;ControllerOperationTrace secondTrace(secondRecorder);ClientId second{};second.value=43;secondTrace.observeBrowserAction(OperationName::Pause,18,second,0x99,20);secondTrace.observeInterfaceRequest(OperationName::Pause,18,102,second,0x99,21);secondTrace.observe(operation(102,SessionOperation::Pause),2,22);secondTrace.observe(result(102,RequestResult::Rejected,RequestRejection::LifecycleNotPausable),2,23);if(secondRecorder.count()!=4)return 6;if(!secondRecorder.read(3,e,payload,sizeof(payload),length)||e.kind!=EventKind::RequestRejected||e.client.value!=43||e.traceId!=0x99||e.correlation.request!=102||e.correlation.parent!=18)return 7;
 MemoryDiagnosticStorage failing;InMemoryDiagnosticRecorder failedRecorder(failing);if(failedRecorder.start(session,status)!=RecorderResult::Accepted)return 8;failing.failNextAppend(StorageResult::WriteFailed);ControllerOperationTrace failedTrace(failedRecorder);failedTrace.observeBrowserAction(OperationName::Start,19,browser,0xAA,30);SessionStatus fs{};failedRecorder.status(fs);if(failedRecorder.count()!=0||fs.droppedRecords==0)return 9;return 0;}
